-- ── the post-migration assertion (the 0084 model) ────────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	e uuid := gen_random_uuid();
	ev uuid := gen_random_uuid();
	actor uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (a) the notifications CHECK is present and NOT VALID.
	IF NOT EXISTS (
		SELECT 1 FROM pg_constraint
		 WHERE conname = 'notifications_source_type_check' AND conrelid = 'notifications'::regclass AND NOT convalidated
	) THEN
		RAISE EXCEPTION 'migration 0100: notifications_source_type_check is missing or not NOT VALID.';
	END IF;
	-- (b) accepted shapes: every endpoint status and disabled reason (the
	-- auto-disable reasons with their episode), a rotation's previous secret,
	-- the failure counters, a rate window; a deleted endpoint beside a live
	-- one with the same URL; every delivery status; a `webhook-disabled`
	-- notification.
	BEGIN
		INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","disabled_reason","disabled_at","disabled_episode_id","secret_sealed","secret_hint","previous_secret_sealed","previous_secret_expires_at","consecutive_failures","failing_since","rate_window_start","rate_window_count","deleted_at","created_by","description")
		VALUES
			(e, t, c, 'https://hooks.acme.in/wms', ARRAY['order.dispatched','receipt.recorded'], 'active', NULL, NULL, NULL, 'v1:x', 'abcd', 'v1:y', now(), 3, now(), now(), 2, NULL, actor, 'ERP'),
			(gen_random_uuid(), t, c, 'https://b.acme.in/', ARRAY['order.dispatched'], 'disabled', 'manual', now(), NULL, 'v1:x', 'abcd', NULL, NULL, 0, NULL, NULL, 0, NULL, actor, NULL),
			(gen_random_uuid(), t, c, 'https://c.acme.in/', ARRAY['order.dispatched'], 'disabled', 'failing', now(), gen_random_uuid(), 'v1:x', 'abcd', NULL, NULL, 10, now(), NULL, 0, NULL, actor, NULL),
			(gen_random_uuid(), t, c, 'https://d.acme.in/', ARRAY['receipt.recorded'], 'disabled', 'gone', now(), gen_random_uuid(), 'v1:x', 'abcd', NULL, NULL, 0, NULL, NULL, 0, NULL, actor, NULL),
			(gen_random_uuid(), t, c, 'https://e.acme.in/', ARRAY['receipt.recorded'], 'disabled', 'client-departed', now(), NULL, 'v1:x', 'abcd', NULL, NULL, 0, NULL, NULL, 0, NULL, actor, NULL),
			(gen_random_uuid(), t, c, 'https://hooks.acme.in/wms', ARRAY['receipt.recorded'], 'deleted', NULL, NULL, NULL, 'v1:x', 'abcd', NULL, NULL, 0, NULL, NULL, 0, now(), actor, NULL);
		INSERT INTO "webhook_events" ("id","tenant_id","client_id","event_type","subject_id","body")
		VALUES (ev, t, c, 'order.dispatched', gen_random_uuid(), '{}'), (gen_random_uuid(), t, c, 'receipt.recorded', gen_random_uuid(), repeat('x', 262144));
		INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","attempts","next_attempt_at","pending_since","claimed_at","succeeded_at","last_status_code","last_error_code","last_duration_ms")
		VALUES
			(gen_random_uuid(), t, c, ev, e, 'pending', 0, now(), now(), NULL, NULL, NULL, NULL, NULL),
			(gen_random_uuid(), t, c, ev, gen_random_uuid(), 'sending', 1, now(), now(), now(), NULL, 500, 'http-500', 12),
			(gen_random_uuid(), t, c, ev, gen_random_uuid(), 'held', 0, now(), now(), NULL, NULL, NULL, NULL, NULL),
			(gen_random_uuid(), t, c, ev, gen_random_uuid(), 'succeeded', 1, now(), now(), NULL, now(), 204, NULL, 40),
			(gen_random_uuid(), t, c, ev, gen_random_uuid(), 'failed', 9, now(), now(), NULL, NULL, NULL, 'target-blocked', 0);
		INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
		VALUES (gen_random_uuid(), t, 'webhook-disabled', gen_random_uuid(), '{"reason":"failing"}'::jsonb, now(), now());
		RAISE EXCEPTION USING ERRCODE = 'P0100', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0100: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0100' THEN
			NULL;
	END;
	-- (c) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'url not https', 'url 2049', 'types empty', 'types unknown', 'types duplicate', 'types null',
		'status unknown', 'deleted without deleted_at', 'deleted_at on active',
		'disabled without reason', 'reason without disabled', 'reason unknown', 'failing without episode',
		'gone without episode', 'episode on manual', 'one previous column', 'failing_since without failures',
		'failures without failing_since', 'rate count without window', 'schema version 2', 'hint 3',
		'description untrimmed', 'description 201', 'url duplicate',
		'event type unknown', 'body 262145', 'subject duplicate',
		'delivery status unknown', 'sending without claimed_at', 'claimed_at on pending', 'succeeded without succeeded_at',
		'status code 99', 'error code with a space', 'negative attempts', 'delivery duplicate',
		'source type unknown'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'url not https' THEN 'webhook_endpoints_url_check'
			WHEN 'url 2049' THEN 'webhook_endpoints_url_check'
			WHEN 'types empty' THEN 'webhook_endpoints_event_types_check'
			WHEN 'types unknown' THEN 'webhook_endpoints_event_types_check'
			WHEN 'types duplicate' THEN 'webhook_endpoints_event_types_check'
			WHEN 'types null' THEN 'webhook_endpoints_event_types_check'
			WHEN 'status unknown' THEN 'webhook_endpoints_status_check'
			WHEN 'deleted without deleted_at' THEN 'webhook_endpoints_status_check'
			WHEN 'deleted_at on active' THEN 'webhook_endpoints_status_check'
			WHEN 'disabled without reason' THEN 'webhook_endpoints_disabled_shape_check'
			WHEN 'reason without disabled' THEN 'webhook_endpoints_disabled_shape_check'
			WHEN 'reason unknown' THEN 'webhook_endpoints_disabled_shape_check'
			WHEN 'failing without episode' THEN 'webhook_endpoints_disabled_shape_check'
			WHEN 'gone without episode' THEN 'webhook_endpoints_disabled_shape_check'
			WHEN 'episode on manual' THEN 'webhook_endpoints_disabled_shape_check'
			WHEN 'one previous column' THEN 'webhook_endpoints_previous_secret_check'
			WHEN 'failing_since without failures' THEN 'webhook_endpoints_failures_check'
			WHEN 'failures without failing_since' THEN 'webhook_endpoints_failures_check'
			WHEN 'rate count without window' THEN 'webhook_endpoints_rate_check'
			WHEN 'schema version 2' THEN 'webhook_endpoints_schema_version_check'
			WHEN 'hint 3' THEN 'webhook_endpoints_secret_check'
			WHEN 'description untrimmed' THEN 'webhook_endpoints_description_check'
			WHEN 'description 201' THEN 'webhook_endpoints_description_check'
			WHEN 'url duplicate' THEN 'webhook_endpoints_client_url_unique'
			WHEN 'event type unknown' THEN 'webhook_events_type_check'
			WHEN 'body 262145' THEN 'webhook_events_body_check'
			WHEN 'subject duplicate' THEN 'webhook_events_subject_unique'
			WHEN 'delivery status unknown' THEN 'webhook_deliveries_status_check'
			WHEN 'sending without claimed_at' THEN 'webhook_deliveries_shape_check'
			WHEN 'claimed_at on pending' THEN 'webhook_deliveries_shape_check'
			WHEN 'succeeded without succeeded_at' THEN 'webhook_deliveries_shape_check'
			WHEN 'status code 99' THEN 'webhook_deliveries_status_code_check'
			WHEN 'error code with a space' THEN 'webhook_deliveries_error_code_check'
			WHEN 'negative attempts' THEN 'webhook_deliveries_shape_check'
			WHEN 'delivery duplicate' THEN 'webhook_deliveries_event_endpoint_unique'
			ELSE 'notifications_source_type_check'
		END;
		BEGIN
			CASE probe
				WHEN 'url not https' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'http://hooks.acme.in/', ARRAY['order.dispatched'], 'v1:x', 'abcd', actor);
				WHEN 'url 2049' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/' || repeat('a', 2036), ARRAY['order.dispatched'], 'v1:x', 'abcd', actor);
				WHEN 'types empty' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY[]::text[], 'v1:x', 'abcd', actor);
				WHEN 'types unknown' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['webhook.test'], 'v1:x', 'abcd', actor);
				WHEN 'types duplicate' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched','order.dispatched'], 'v1:x', 'abcd', actor);
				WHEN 'types null' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched', NULL], 'v1:x', 'abcd', actor);
				WHEN 'status unknown' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'archived', 'v1:x', 'abcd', actor);
				WHEN 'deleted without deleted_at' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'deleted', 'v1:x', 'abcd', actor);
				WHEN 'deleted_at on active' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","deleted_at","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], now(), 'v1:x', 'abcd', actor);
				WHEN 'disabled without reason' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'disabled', 'v1:x', 'abcd', actor);
				WHEN 'reason without disabled' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","disabled_reason","disabled_at","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'manual', now(), 'v1:x', 'abcd', actor);
				WHEN 'reason unknown' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","disabled_reason","disabled_at","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'disabled', 'paused', now(), 'v1:x', 'abcd', actor);
				WHEN 'failing without episode' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","disabled_reason","disabled_at","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'disabled', 'failing', now(), 'v1:x', 'abcd', actor);
				WHEN 'gone without episode' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","disabled_reason","disabled_at","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'disabled', 'gone', now(), 'v1:x', 'abcd', actor);
				WHEN 'episode on manual' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","status","disabled_reason","disabled_at","disabled_episode_id","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'disabled', 'manual', now(), gen_random_uuid(), 'v1:x', 'abcd', actor);
				WHEN 'one previous column' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","previous_secret_sealed","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'v1:y', 'v1:x', 'abcd', actor);
				WHEN 'failing_since without failures' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","failing_since","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], now(), 'v1:x', 'abcd', actor);
				WHEN 'failures without failing_since' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","consecutive_failures","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 2, 'v1:x', 'abcd', actor);
				WHEN 'rate count without window' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","rate_window_count","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 1, 'v1:x', 'abcd', actor);
				WHEN 'schema version 2' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","schema_version","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 2, 'v1:x', 'abcd', actor);
				WHEN 'hint 3' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'v1:x', 'abc', actor);
				WHEN 'description untrimmed' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by","description") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'v1:x', 'abcd', actor, ' ERP');
				WHEN 'description 201' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by","description") VALUES (gen_random_uuid(), t, c, 'https://h.in/', ARRAY['order.dispatched'], 'v1:x', 'abcd', actor, repeat('d', 201));
				WHEN 'url duplicate' THEN
					INSERT INTO "webhook_endpoints" ("id","tenant_id","client_id","url","event_types","secret_sealed","secret_hint","created_by")
					VALUES (gen_random_uuid(), t, c, 'https://dup.acme.in/', ARRAY['order.dispatched'], 'v1:x', 'abcd', actor),
					       (gen_random_uuid(), t, c, 'https://dup.acme.in/', ARRAY['receipt.recorded'], 'v1:x', 'abcd', actor);
				WHEN 'event type unknown' THEN
					INSERT INTO "webhook_events" ("id","tenant_id","client_id","event_type","subject_id","body") VALUES (gen_random_uuid(), t, c, 'webhook.test', gen_random_uuid(), '{}');
				WHEN 'body 262145' THEN
					INSERT INTO "webhook_events" ("id","tenant_id","client_id","event_type","subject_id","body") VALUES (gen_random_uuid(), t, c, 'order.dispatched', gen_random_uuid(), repeat('x', 262145));
				WHEN 'subject duplicate' THEN
					INSERT INTO "webhook_events" ("id","tenant_id","client_id","event_type","subject_id","body")
					VALUES (gen_random_uuid(), t, c, 'order.dispatched', e, '{}'), (gen_random_uuid(), t, c, 'order.dispatched', e, '{}');
				WHEN 'delivery status unknown' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since") VALUES (gen_random_uuid(), t, c, ev, e, 'expired', now(), now());
				WHEN 'sending without claimed_at' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since") VALUES (gen_random_uuid(), t, c, ev, e, 'sending', now(), now());
				WHEN 'claimed_at on pending' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since","claimed_at") VALUES (gen_random_uuid(), t, c, ev, e, 'pending', now(), now(), now());
				WHEN 'succeeded without succeeded_at' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since") VALUES (gen_random_uuid(), t, c, ev, e, 'succeeded', now(), now());
				WHEN 'status code 99' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since","last_status_code") VALUES (gen_random_uuid(), t, c, ev, e, 'failed', now(), now(), 99);
				WHEN 'error code with a space' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since","last_error_code") VALUES (gen_random_uuid(), t, c, ev, e, 'failed', now(), now(), 'http 500');
				WHEN 'negative attempts' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","attempts","next_attempt_at","pending_since") VALUES (gen_random_uuid(), t, c, ev, e, 'pending', -1, now(), now());
				WHEN 'delivery duplicate' THEN
					INSERT INTO "webhook_deliveries" ("id","tenant_id","client_id","event_id","endpoint_id","status","next_attempt_at","pending_since")
					VALUES (gen_random_uuid(), t, c, ev, e, 'pending', now(), now()), (gen_random_uuid(), t, c, ev, e, 'pending', now(), now());
				WHEN 'source type unknown' THEN
					INSERT INTO "notifications" ("id","tenant_id","source_type","source_id","summary","raised_at","surfaced_at")
					VALUES (gen_random_uuid(), t, 'webhook-disabled-x', gen_random_uuid(), '{}'::jsonb, now(), now());
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0100: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "webhook_endpoints" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "webhook_events" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "webhook_deliveries" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "notifications" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0100: a probe row survived.';
	END IF;
END $$;
